//! Text: proportional, anti-aliased fonts ([`crate::fonts`], generated by tools/font.py) drawn through
//! [`Canvas::blit`]. Each glyph is one window of `advance` x `height` pixels, blended onto a known background
//! colour, so a string overwrites what was under it without a clear first.

use crate::ui::Canvas;

/// One character: its cell is `advance` x the font height; the ink is the `w` x `h` box at (`x`, `y`) in the
/// cell, 4 bits of coverage per pixel (high nibble first), row by row from byte `at` of [`Font::alpha`].
pub struct Glyph {
    /// Cell width: where the next character starts.
    pub advance: u8,
    /// Ink box left edge, in the cell.
    pub x: u8,
    /// Ink box top edge, in the cell.
    pub y: u8,
    /// Ink box width.
    pub w: u8,
    /// Ink box height.
    pub h: u8,
    /// First byte of the ink in [`Font::alpha`].
    pub at: u32,
}

/// A font: printable ASCII (0x20..=0x7e); other characters are drawn as `?`.
pub struct Font {
    /// Line height in pixels (the height of every cell).
    pub height: u8,
    /// Glyphs for 0x20..=0x7e.
    pub glyphs: &'static [Glyph],
    /// Coverage of all glyphs, 4 bits per pixel.
    pub alpha: &'static [u8],
}

impl Font {
    fn glyph(&self, c: char) -> &Glyph {
        let i = (c as usize).wrapping_sub(0x20);
        match self.glyphs.get(i) {
            Some(g) => g,
            None => &self.glyphs[usize::from(b'?' - 0x20)],
        }
    }

    /// Coverage 0..=15 of pixel (`px`, `py`) of glyph `g`'s cell.
    fn coverage(&self, g: &Glyph, px: u32, py: u32) -> u8 {
        let (x, y) = (px.wrapping_sub(u32::from(g.x)), py.wrapping_sub(u32::from(g.y)));
        if x >= u32::from(g.w) || y >= u32::from(g.h) {
            return 0;
        }
        let n = y * u32::from(g.w) + x;
        let byte = self.alpha.get((g.at + n / 2) as usize).copied().unwrap_or(0);
        if n % 2 == 0 { byte >> 4 } else { byte & 0xf }
    }

    /// Width of `s` in pixels.
    pub fn width(&self, s: &str) -> u32 {
        s.chars().map(|c| u32::from(self.glyph(c).advance)).sum()
    }
}

/// `fg` over `bg` at coverage `a` (0..=15), channel by channel in RGB565.
///
/// ```
/// use bryton_rustfw::text::blend;
/// assert_eq!(blend(0xffff, 0x0000, 15), 0xffff);
/// assert_eq!(blend(0xffff, 0x0000, 0), 0x0000);
/// assert_eq!(blend(0xf800, 0x0000, 8) >> 11, 17); // red 31 at 8/15: 17
/// ```
pub fn blend(fg: u16, bg: u16, a: u8) -> u16 {
    let a = u32::from(a.min(15));
    let mix = |shift: u32, mask: u32| {
        let (f, b) = ((u32::from(fg) >> shift) & mask, (u32::from(bg) >> shift) & mask);
        ((f * a + b * (15 - a) + 7) / 15) << shift
    };
    (mix(11, 0x1f) | mix(5, 0x3f) | mix(0, 0x1f)) as u16
}

/// How text looks: a font and its colours. The UI defines its styles once (ui.rs) and draws with them.
pub struct Style {
    /// The font.
    pub font: &'static Font,
    /// Ink colour, RGB565.
    pub fg: u16,
    /// Background the ink is blended onto: what is under the text.
    pub bg: u16,
}

/// Where a string goes, relative to the `x` given to [`draw`].
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Align {
    /// `x` is the left edge.
    Left,
    /// `x` is the centre.
    Centre,
    /// `x` is the right edge.
    Right,
}

/// Draws `s` in `style` with its cells' top at `y`, and returns its width. Callers keep it on screen.
pub fn draw(c: &mut impl Canvas, style: &Style, x: u32, y: u32, align: Align, s: &str) -> u32 {
    let Style { font, fg, bg } = *style;
    let width = font.width(s);
    let mut x = match align {
        Align::Left => x,
        Align::Centre => x.saturating_sub(width / 2),
        Align::Right => x.saturating_sub(width),
    };
    let mut palette = [bg; 16];
    for (a, p) in palette.iter_mut().enumerate() {
        *p = blend(fg, bg, a as u8);
    }
    for ch in s.chars() {
        let g = font.glyph(ch);
        let w = u32::from(g.advance);
        c.blit(x, y, w, u32::from(font.height), &mut |px, py| palette[usize::from(font.coverage(g, px, py))]);
        x += w;
    }
    width
}

/// Draws `s` in a box `w` wide from `x` (aligned inside it) and paints the rest of the box with the background, so a
/// shorter value leaves nothing of the previous one. Text wider than the box is cut at the box's last whole
/// character. Returns the width of the text drawn.
pub fn draw_in(c: &mut impl Canvas, style: &Style, x: u32, y: u32, w: u32, align: Align, s: &str) -> u32 {
    let font = style.font;
    let mut end = s.len();
    while font.width(&s[..end]) > w {
        end = s[..end].char_indices().next_back().map_or(0, |(i, _)| i);
    }
    let s = &s[..end];
    let tw = font.width(s);
    let left = match align {
        Align::Left => 0,
        Align::Centre => (w - tw) / 2,
        Align::Right => w - tw,
    };
    let h = u32::from(font.height);
    c.fill(x, y, left, h, style.bg);
    draw(c, style, x + left, y, Align::Left, s);
    c.fill(x + left + tw, y, w - left - tw, h, style.bg);
    tw
}

/// A line of text built with `write!` into a fixed buffer (no heap): `N` bytes, the rest is dropped.
///
/// ```
/// use core::fmt::Write;
/// let mut l = bryton_rustfw::text::Line::<16>::new();
/// write!(l, "{:.1} km/h", 25.44).unwrap();
/// assert_eq!(l.as_str(), "25.4 km/h");
/// ```
pub struct Line<const N: usize> {
    buf: [u8; N],
    len: usize,
}

impl<const N: usize> Default for Line<N> {
    fn default() -> Self {
        Self::new()
    }
}

impl<const N: usize> Line<N> {
    /// An empty line.
    pub const fn new() -> Self {
        Line { buf: [0; N], len: 0 }
    }

    /// The text so far.
    pub fn as_str(&self) -> &str {
        // Only whole characters are ever stored (write_str), so this never fails.
        core::str::from_utf8(&self.buf[..self.len]).unwrap_or("")
    }

    /// Empties it.
    pub fn clear(&mut self) {
        self.len = 0;
    }
}

impl<const N: usize> core::fmt::Write for Line<N> {
    fn write_str(&mut self, s: &str) -> core::fmt::Result {
        for c in s.chars() {
            let mut tmp = [0; 4];
            let bytes = c.encode_utf8(&mut tmp).as_bytes();
            let Some(dst) = self.buf.get_mut(self.len..self.len + bytes.len()) else {
                return Ok(()); // full: the rest is dropped, which is fine for a screen line
            };
            dst.copy_from_slice(bytes);
            self.len += bytes.len();
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::fonts::{SANS_16, SANS_BOLD_32};
    use crate::ui::tests::Frame;
    use crate::ui::{BLACK, WHITE};

    const SMALL: Style = Style { font: &SANS_16, fg: WHITE, bg: BLACK };
    const BIG: Style = Style { font: &SANS_BOLD_32, fg: WHITE, bg: BLACK };

    #[test]
    fn every_glyph_fits_its_cell_and_its_data() {
        for font in [&SANS_16, &SANS_BOLD_32] {
            assert_eq!(font.glyphs.len(), 0x7f - 0x20);
            for (i, g) in font.glyphs.iter().enumerate() {
                assert!(g.x + g.w <= g.advance && g.y + g.h <= font.height, "glyph {i} outside its cell");
                let bytes = (u32::from(g.w) * u32::from(g.h)).div_ceil(2);
                assert!((g.at + bytes) as usize <= font.alpha.len(), "glyph {i} past the data");
            }
        }
    }

    /// Text lands where its width says, with ink inside and the background colour around it.
    #[test]
    fn draws_in_its_box() {
        let mut f = Frame::new();
        let w = draw(&mut f, &SMALL, 120, 10, Align::Centre, "USB");
        assert_eq!(w, SANS_16.width("USB"));
        let x0 = 120 - w / 2;
        let ink = |x: u32, y: u32| f.at(x, y) != BLACK;
        assert!((x0..x0 + w).any(|x| (10..10 + 19).any(|y| ink(x, y))));
        assert!((0..240).all(|x| !ink(x, 9) && !ink(x, 10 + 19)), "ink outside the line");
        assert!((0..x0).chain(x0 + w..240).all(|x| (0..40).all(|y| !ink(x, y))), "ink outside the width");
        assert!((x0..x0 + w).any(|x| (10..29).any(|y| f.at(x, y) == WHITE)), "no fully covered pixel");
    }

    /// Every character of every font into target/sim/fonts.bmp: a sheet to judge sizes and spacing on the host.
    #[test]
    fn font_sheet() {
        extern crate std;
        let mut f = Frame::new();
        let ascii: std::string::String = (0x20u8..0x7f).map(char::from).collect();
        let mut y = 0;
        // All of ASCII in the small font; what a bike computer shows in the big one (all of it would not fit).
        for (style, sample) in [(&SMALL, ascii.as_str()), (&BIG, "0123456789 :.,-+%/ 12:34 25.4 km/h 142 bpm 250 W")] {
            let mut line = std::string::String::new();
            for c in sample.chars() {
                if style.font.width(&line) + u32::from(style.font.glyph(c).advance) > 236 {
                    draw(&mut f, style, 2, y, Align::Left, &line);
                    y += u32::from(style.font.height);
                    line.clear();
                }
                line.push(c);
            }
            draw(&mut f, style, 2, y, Align::Left, &line);
            y += u32::from(style.font.height) + 4;
        }
        let dir = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("target/sim");
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("fonts.bmp"), crate::sim::bmp(&f.px)).unwrap();
    }

    /// A shorter value in the same box leaves nothing of the longer one; the box is the only thing touched.
    #[test]
    fn draw_in_clears_the_rest_of_its_box() {
        for align in [Align::Left, Align::Centre, Align::Right] {
            let (mut a, mut b) = (Frame::new(), Frame::new());
            draw_in(&mut a, &BIG, 20, 50, 200, align, "188.8");
            draw_in(&mut a, &BIG, 20, 50, 200, align, "7");
            draw_in(&mut b, &BIG, 20, 50, 200, align, "7");
            assert!(a.px == b.px, "{align:?}");
        }
        let mut f = Frame::new();
        assert_eq!(draw_in(&mut f, &BIG, 0, 0, 30, Align::Left, "12345"), BIG.font.width("1"), "cut to the box");
    }

    #[test]
    fn line_drops_what_does_not_fit() {
        use core::fmt::Write;
        let mut l = Line::<4>::new();
        write!(l, "a\u{e9}cd").unwrap(); // the e acute takes 2 bytes
        assert_eq!(l.as_str(), "a\u{e9}c");
        l.clear();
        write!(l, "{}", 12).unwrap();
        assert_eq!(l.as_str(), "12");
    }

    #[test]
    fn unknown_characters_are_question_marks() {
        assert_eq!(SANS_16.width("é"), SANS_16.width("?"));
        let (mut a, mut b) = (Frame::new(), Frame::new());
        draw(&mut a, &SMALL, 0, 0, Align::Left, "\u{1f980}");
        draw(&mut b, &SMALL, 0, 0, Align::Left, "?");
        assert!(a.px == b.px);
    }

    #[test]
    fn right_aligned_text_ends_at_x() {
        let mut f = Frame::new();
        let w = draw(&mut f, &BIG, 200, 100, Align::Right, "42");
        assert!((200..240).all(|x| (100..140).all(|y| f.at(x, y) == BLACK)));
        assert!((200 - w..200).any(|x| (100..140).any(|y| f.at(x, y) == WHITE)));
    }
}
